package co.edu.uco.seguridad.pdp.assignments.application.usecase.impl;
import co.edu.uco.seguridad.pdp.assignments.application.primaryport.request.ListApplicationAssignmentsPageRequest; import co.edu.uco.seguridad.pdp.assignments.application.primaryport.response.AssignmentResponse; import co.edu.uco.seguridad.pdp.assignments.application.secondaryport.repository.AssignmentRepository; import co.edu.uco.seguridad.pdp.assignments.application.usecase.ListApplicationAdministratorsPageUseCase; import co.edu.uco.seguridad.pdp.commons.model.ResultPage; import co.edu.uco.seguridad.pdp.roles.application.primaryport.request.RoleNameInScopeQuery; import co.edu.uco.seguridad.pdp.roles.application.rule.validator.RoleLookupByNameInScopeValidator; import co.edu.uco.seguridad.pdp.roles.domain.model.*; import co.edu.uco.seguridad.shared.port.TimeProvider; import reactor.core.publisher.Mono;
public final class ListApplicationAdministratorsPageUseCaseImpl implements ListApplicationAdministratorsPageUseCase {private static final RoleName ADMIN=new RoleName("ADMIN");private final RoleLookupByNameInScopeValidator roles;private final AssignmentRepository assignments;private final TimeProvider time;public ListApplicationAdministratorsPageUseCaseImpl(RoleLookupByNameInScopeValidator roles,AssignmentRepository assignments,TimeProvider time){this.roles=roles;this.assignments=assignments;this.time=time;}public Mono<ResultPage<AssignmentResponse>> execute(ListApplicationAssignmentsPageRequest i){return roles.execute(new RoleNameInScopeQuery(ADMIN,RoleScope.ofApplication(i.tenantId(),i.applicationId()))).flatMap(role->assignments.findActivePageByRoleAndApplication(role,i.tenantId(),i.applicationId(),time.now(),i.window())).map(p->p.map(a->new AssignmentResponse(a.id(),a.userId(),a.tenantId(),a.applicationId(),a.roleId(),a.validity().validFrom(),a.validity().validUntil())));}}
